      line-height: 1.7;
    }

    .highlight {
      color: #e63946;
      font-weight: bold;
    }

    .section {
      margin-bottom: 30px;
    }

    .cta {
      display: inline-block;
      background-color: #e63946;
      color: white;
      padding: 12px 24px;
      font-size: 1.2em;
      text-decoration: none;
      border-radius: 5px;
      margin-top: 40px;
      text-align: center;
      width: 100%;
      max-width: 300px;
      transition: background-color 0.3s ease;
      margin-left: auto;
      margin-right: auto;
    }

    .cta:hover {
      background-color: #d62828;
    }

    @media (max-width: 600px) {
      .container {
        padding: 20px;
      }

      h1 {
        font-size: 2em;
      }

      h2 {
        font-size: 1.5em;
      }

